<script>
// ─────────────────────────────────────────────────────────────
// COIN RENDERER  (pure 2D canvas, software ray-march style)
// ─────────────────────────────────────────────────────────────

(function(){
"use strict";

// ── Math helpers ──────────────────────────────────────────────
const TAU = Math.PI * 2;
const clamp = (v,a,b) => Math.max(a,Math.min(b,v));
const lerp  = (a,b,t) => a + (b-a)*t;

// ── Colour helpers ────────────────────────────────────────────
function rgb(r,g,b){return `rgb(${r|0},${g|0},${b|0})`;}
function rgbf(r,g,b){
  return `rgb(${clamp(r*255,0,255)|0},${clamp(g*255,0,255)|0},${clamp(b*255,0,255)|0})`;
}
function hexToRgb(h){
  const n=parseInt(h.slice(1),16);
  return [(n>>16)&255,(n>>8)&255,n&255];
}

// ── Per-pixel coin renderer ───────────────────────────────────
// We build the coin into an offscreen ImageData so we can do
// real per-pixel lighting.

function renderCoin(ctx, cx, cy, R, yAngle, xAngle, palette){
  // yAngle: rotation about Y axis (0-TAU)  → determines which face shows
  // xAngle: tilt about X axis  (small rock)
  // palette: {face, rim, specColor, hiColor, textCol}

  const W = ctx.canvas.width, H = ctx.canvas.height;
  const imgd = ctx.createImageData(W,H);
  const px = imgd.data;

  // coin thickness ratio (half-thickness / radius)
  const THICK = 0.08;

  // light direction (world space, normalised)
  const LX= 0.6, LY=0.7, LZ=0.7;
  const Llen = Math.sqrt(LX*LX+LY*LY+LZ*LZ);
  const lx=LX/Llen, ly=LY/Llen, lz=LZ/Llen;

  // camera is at +Z, looking toward -Z  (orthographic projection)
  // coin orientation:
  //   Y-rotation by yAngle → normals transform
  //   X-rotation by xAngle → small tilt

  const cosY=Math.cos(yAngle), sinY=Math.sin(yAngle);
  const cosX=Math.cos(xAngle), sinX=Math.sin(xAngle);

  // which face is toward camera?
  // Face normal in model space: front=(0,0,1), back=(0,0,-1)
  // After Y-rotation: front_z = cosY  (positive = visible)
  const frontVisible = cosY >= 0;

  // rim color
  const rc = palette.rim;

  // reeded edge: number of reeds
  const REEDS = 60;

  // For each screen pixel, raycast
  for(let py=0;py<H;py++){
    for(let ppx=0;ppx<W;ppx++){
      // map pixel to coin-local coordinates
      // apply inverse camera transform (orthographic)
      let sx = (ppx - cx);
      let sy = (py  - cy);

      // apply inverse X rotation to get model-space y,z of ray
      // ray in world: dir=(0,0,-1), origin=(sx,sy,1000)
      // model-space ray origin after inverse rotations:
      // inverse X: y'= cosX*sy + sinX*sz,  z'= -sinX*sy + cosX*sz  (sz component we ignore for origin in plane)
      // We do a simple slab test for the two faces + cylinder rim

      // Undo Y rotation on screen x to get model-local x component
      // For orthographic: model x = sx*cosY + sz_world*sinY  but sz_world of pixel origin isn't meaningful
      // Instead work in world-projected space:
      // The coin disc after rotations: a pixel (sx,sy) maps to the coin if:
      //   |sx| / cosY ≤ R  (foreshortened along x when rotated)
      //   |sy| ≤ R
      //   sx^2/(cosY)^2 + sy^2 ≤ R^2  ... only valid when |cosY|>threshold, else we see the rim

      // Correct approach: for each screen pixel, check intersection with
      // rotated coin (disc + cylinder). The coin is in X-Z plane rotated by yAngle about Y,
      // then by xAngle about X.

      // Coin occupies: |z_model| ≤ THICK*R (slab), x_model^2+y_model^2 ≤ R^2

      // World-space (after model rotations, before projection):
      // model → world:  first rotate about X by xAngle, then about Y by yAngle
      // world X  = cosY * xm  + sinY*(sinX*ym + cosX*zm)
      // world Y  =             cosX*ym - sinX*zm
      // world Z  = -sinY * xm + cosY*(sinX*ym + cosX*zm)

      // Inverse (world → model):
      // xm =  cosY*wx              - sinY*wz
      // ym =  sinY*sinX*wx + cosX*wy + cosY*sinX*wz
      // zm =  sinY*cosX*wx - sinX*wy + cosY*cosX*wz

      // Orthographic projection: wx=sx, wy=sy, wz=? 
      // Ray goes through (sx, sy, *) in world space.
      // We need to find wz values where model constraints are satisfied.

      // For FACE intersection (slab |zm| ≤ THICK*R):
      // zm = sinY*cosX*sx - sinX*sy + cosY*cosX*wz = ±THICK*R
      // → wz = (±THICK*R - sinY*cosX*sx + sinX*sy) / (cosY*cosX)
      // then check xm^2+ym^2 ≤ R^2

      // For RIM intersection (cylinder x^2+y^2 = R^2, |z|≤THICK*R):
      // substituting wz from ray parameterization gives a quadratic in wz
      // For brevity: we pick the closest valid intersection

      let hit = false;
      let hitType = 'none'; // 'front','back','rim'
      let nx=0,ny=0,nz=0;  // world-space surface normal
      let ux=0,uy=0;       // model-space UV on face (for texture)
      let rimAngle=0;       // for reed computation

      const CcX = cosY, CcZ = cosX;
      const B = cosY * cosX; // coefficient of wz in zm formula

      if(Math.abs(B) > 0.01){
        // Face intersections
        const base_zm = sinY*cosX*sx - sinX*sy;
        for(let sign=-1;sign<=1;sign+=2){
          const zm_target = sign * THICK * R;
          const wz = (zm_target - base_zm) / B;
          // compute xm, ym
          const xm = cosY*sx - sinY*wz;
          const ym = sinY*sinX*sx + cosX*sy + cosY*sinX*wz;
          if(xm*xm + ym*ym <= R*R){
            // valid face hit; sign=+1 → front face (zm=+THICK), sign=-1 → back
            const isFront = (sign === 1);
            // normal in model space: (0,0,sign) → world space
            // world normal = M * (0,0,sign)
            const wnx = sinY*cosX*sign;
            const wny = -sinX*sign;
            const wnz = cosY*cosX*sign;
            // check if facing camera (+Z direction)
            if(wnz > 0){
              hit=true;
              hitType = isFront ? 'front':'back';
              nx=wnx;ny=wny;nz=wnz;
              ux=xm/R; uy=ym/R;
              break;
            }
          }
        }
      }

      // If no face hit, try rim (cylinder)
      if(!hit){
        // Model-space coordinates as linear function of wz:
        // xm(wz) = cosY*sx - sinY*wz  = A0 + A1*wz
        // ym(wz) = sinY*sinX*sx + cosX*sy + cosY*sinX*wz = B0 + B1*wz
        // cylinder: xm^2 + ym^2 = R^2
        const A0 = cosY*sx, A1 = -sinY;
        const B0 = sinY*sinX*sx + cosX*sy, B1 = cosY*sinX;
        const a = A1*A1 + B1*B1;
        const b2 = A0*A1 + B0*B1; // b/2
        const c = A0*A0 + B0*B0 - R*R;
        const disc = b2*b2 - a*c;
        if(a > 1e-6 && disc >= 0){
          const sqd = Math.sqrt(disc);
          // two solutions; pick the one with largest wz (closest to camera = largest world Z)
          for(let sg=1;sg>=-1;sg-=2){
            const wz = (-b2 + sg*sqd)/a;
            const xm = A0 + A1*wz;
            const ym = B0 + B1*wz;
            const zm = sinY*cosX*sx - sinX*sy + cosY*cosX*wz;
            if(Math.abs(zm) <= THICK*R){
              // outward model normal = (xm/R, ym/R, 0)
              const mnx = xm/R, mny = ym/R, mnz = 0;
              // to world:
              const wnx = cosY*mnx + sinY*(sinX*mny);
              const wny = cosX*mny;
              const wnz = -sinY*mnx + cosY*(sinX*mny);
              if(wnz > -0.5){ // accept rim hits even slightly away from camera
                hit=true;
                hitType='rim';
                nx=wnx;ny=wny;nz=wnz;
                // rim angle for reeds (use model xm,ym)
                rimAngle = Math.atan2(ym, xm);
                // zm in [−THICK,+THICK]*R maps to v in [0,1]
                ux=zm/(THICK*R)*0.5+0.5; // repurpose ux as height
                break;
              }
            }
          }
        }
      }

      if(!hit) continue;

      // ── lighting ──────────────────────────────────────────
      const nlen = Math.sqrt(nx*nx+ny*ny+nz*nz);
      const nnx=nx/nlen,nny=ny/nlen,nnz=nz/nlen;

      // diffuse
      const diff = clamp(nnx*lx + nny*ly + nnz*lz, 0, 1);

      // specular (Blinn-Phong); view dir = (0,0,1)
      const hx=(lx+0)*0.5, hy=(ly+0)*0.5, hz=(lz+1)*0.5;
      const hlen=Math.sqrt(hx*hx+hy*hy+hz*hz);
      const spec = Math.pow(clamp((nnx*hx+nny*hy+nnz*hz)/hlen,0,1), 80);

      // Fresnel-ish rim brightness
      const fres = Math.pow(1-Math.abs(nnz),3)*0.4;

      let r=0,g=0,b=0;

      if(hitType==='rim'){
        // reeded edge
        const reed = Math.sin(rimAngle * REEDS);
        const reedVal = clamp(reed*0.5+0.5,0,1);
        const base = rc;
        const rimDark = palette.rimDark;
        r = lerp(rimDark[0],base[0],reedVal)/255;
        g = lerp(rimDark[1],base[1],reedVal)/255;
        b = lerp(rimDark[2],base[2],reedVal)/255;
        // light the rim
        const rimDiff = diff*0.8 + 0.2;
        r *= rimDiff; g *= rimDiff; b *= rimDiff;
        r += spec*palette.specColor[0]/255;
        g += spec*palette.specColor[1]/255;
        b += spec*palette.specColor[2]/255;
      } else {
        // face (front or back)
        const faceCol = (hitType==='front') ? palette.face : palette.back;
        const texR = faceCol[0]/255, texG=faceCol[1]/255, texB=faceCol[2]/255;

        // embossed detail: we simulate with a height-field sampler
        let emboss = 0;
        const dist2 = ux*ux + uy*uy;
        if(hitType==='front'){
          emboss = frontEmboss(ux, uy, dist2);
        } else {
          emboss = backEmboss(ux, uy, dist2);
        }
        // emboss modifies the effective normal slightly
        const bump = emboss * 0.35;
        const bnx = nnx + bump * Math.sign(ux+0.001);
        const bny = nny + bump * Math.sign(uy+0.001);
        const bnz = nnz;
        const blen = Math.sqrt(bnx*bnx+bny*bny+bnz*bnz);
        const fnx=bnx/blen,fny=bny/blen,fnz=bnz/blen;

        const bdiff = clamp(fnx*lx+fny*ly+fnz*lz,0,1);
        const bhx=(lx)*0.5,bhy=(ly)*0.5,bhz=(lz+1)*0.5;
        const bhlen=Math.sqrt(bhx*bhx+bhy*bhy+bhz*bhz);
        const bspec = Math.pow(clamp((fnx*bhx+fny*bhy+fnz*bhz)/bhlen,0,1),100);

        const ambient = 0.18;
        r = texR*(ambient + bdiff*0.75) + bspec*palette.specColor[0]/255 + fres*texR;
        g = texG*(ambient + bdiff*0.75) + bspec*palette.specColor[1]/255 + fres*texG;
        b = texB*(ambient + bdiff*0.75) + bspec*palette.specColor[2]/255 + fres*texB;

        // High-frequency emboss shading
        const eShade = emboss * 0.45;
        r += eShade*palette.hiColor[0]/255;
        g += eShade*palette.hiColor[1]/255;
        b += eShade*palette.hiColor[2]/255;
      }

      r=clamp(r,0,1); g=clamp(g,0,1); b=clamp(b,0,1);
      // gamma
      r=Math.sqrt(r); g=Math.sqrt(g); b=Math.sqrt(b);

      const idx = (py*W + ppx)*4;
      px[idx]   = r*255;
      px[idx+1] = g*255;
      px[idx+2] = b*255;
      px[idx+3] = 255;
    }
  }
  ctx.putImageData(imgd, 0, 0);
}

// ── Emboss functions ──────────────────────────────────────────
// Return a value in [-1,+1]; positive = raised, negative = recessed.
// (ux,uy) in [-1,+1] model-space face coords

function sdCircle(x,y,r){return Math.sqrt(x*x+y*y)-r;}
function sdBox(x,y,w,h){const qx=Math.abs(x)-w,qy=Math.abs(y)-h;return Math.sqrt(Math.max(qx,0)**2+Math.max(qy,0)**2)+Math.min(Math.max(qx,qy),0);}
function sdRing(x,y,r,t){return Math.abs(Math.sqrt(x*x+y*y)-r)-t;}

// Map sdf to an emboss height (smooth ridge)
function sdfToRidge(d, sharpness=18){
  return Math.exp(-d*d*sharpness);
}
function sdfToGroove(d, sharpness=18){
  return -sdfToRidge(d, sharpness);
}

function frontEmboss(ux, uy, dist2){
  let h = 0;
  // Outer decorative ring
  h += sdfToRidge(sdRing(ux,uy, 0.88, 0.03), 900) * 0.6;
  // Inner ring
  h += sdfToRidge(sdRing(ux,uy, 0.72, 0.02), 1200) * 0.4;
  // Second inner ring
  h += sdfToRidge(sdRing(ux,uy, 0.55, 0.015), 1500) * 0.3;

  // Central "W" emblem: approximated as geometric primitives
  // Central shield shape
  const shieldD = Math.max(sdBox(ux,uy+0.05,0.18,0.22), -sdCircle(ux,uy+0.28,0.18));
  h += sdfToRidge(shieldD, 120) * 0.9;

  // Star burst (8 points): sum of rotated narrow boxes
  for(let i=0;i<8;i++){
    const a = i * Math.PI/4;
    const rx = ux*Math.cos(a)+uy*Math.sin(a);
    const ry = -ux*Math.sin(a)+uy*Math.cos(a);
    h += sdfToRidge(sdBox(rx,ry-0.38,0.025,0.08),300)*0.4;
  }

  // "WT" text approximation: two rectangles
  h += sdfToRidge(sdBox(ux+0.05,uy,0.025,0.1),400)*0.6; // left stroke of W
  h += sdfToRidge(sdBox(ux-0.05,uy,0.025,0.1),400)*0.6; // right stroke
  h += sdfToRidge(sdBox(ux,uy-0.08,0.06,0.018),600)*0.5; // crossbar T

  // Dots at cardinal positions on inner ring
  for(let i=0;i<12;i++){
    const a=i*TAU/12;
    const dx=ux-Math.cos(a)*0.64, dy=uy-Math.sin(a)*0.64;
    h += sdfToRidge(sdCircle(dx,dy,0.025),800)*0.35;
  }

  return h;
}

function backEmboss(ux, uy, dist2){
  let h = 0;
  // Outer ring
  h += sdfToRidge(sdRing(ux,uy, 0.88, 0.03), 900) * 0.5;
  // Inner ring
  h += sdfToRidge(sdRing(ux,uy, 0.68, 0.018), 1200) * 0.35;

  // "10,000 TOKENS" — approximated as horizontal bars (like LED segments)
  const lines = [
    [0, 0.08],
    [0, -0.04],
    [0, -0.16],
  ];
  lines.forEach(([ly2])=>{
    h += sdfToRidge(sdBox(ux, uy-ly2, 0.35, 0.02),500)*0.55;
  });
  // Vertical serifs on ends
  for(let sx=-0.35;sx<=0.36;sx+=0.70){
    h += sdfToRidge(sdBox(ux-sx, uy, 0.02, 0.14),600)*0.5;
  }
  // Zero shapes (two oval outlines)
  for(let ox=-0.15;ox<=0.16;ox+=0.30){
    h += sdfToRidge(sdRing(ux-ox, uy, 0.1, 0.02),800)*0.45;
  }
  // Denomination band
  h += sdfToRidge(sdBox(ux, uy+0.32, 0.4, 0.05),300)*0.3;
  // Stars top/bottom
  for(let sa=-1;sa<=1;sa+=2){
    const dy2 = uy - sa*0.6;
    h += sdfToRidge(sdCircle(ux, dy2, 0.06),400)*0.4;
    h += sdfToRidge(sdBox(ux,dy2,0.04,0.09),600)*0.35;
    h += sdfToRidge(sdBox(ux,dy2,0.09,0.04),600)*0.35;
  }
  return h;
}

// ── Palette definitions ───────────────────────────────────────
function makePalette(type){
  const p = {};
  switch(type){
    case 'hero':
    case 'gold':
      p.face    = [210,170, 60];
