// The full loop is 4 seconds; t in [0,1] maps to one full loop.
// Loop: Y rotates 360°, X tilts ±15° (sinusoidal)
function getAngles(t){
  const yAngle = t * TAU;                            // full Y rotation
  const xAngle = Math.sin(t * TAU) * 0.18;           // gentle X tilt (±~10°)
  return {yAngle, xAngle};
}

const heroPalette = makePalette('hero');

function renderFrame(t){
  // Clear
  heroCtx.clearRect(0,0,W,H);

  const {yAngle, xAngle} = getAngles(t);
  renderCoin(heroCtx, cx, cy, R, yAngle, xAngle, heroPalette);
}

function loop(ts){
  if(!animRunning) return;
  // 4-second loop
  currentT = (ts / 4000) % 1;
  renderFrame(currentT);
  rafId = requestAnimationFrame(loop);
}

// Start
rafId = requestAnimationFrame(loop);

